export const GF_UI_CSS = "/*\n * Gotcha Force — shared UI styles for the 1-to-1 recreation component library.\n *\n * All classes are prefixed `gf-` to stay scoped. Palette + type feel are pulled\n * from the real captured reference screens in apps/game/reference/captures/.\n * Reference real extracted art via /ui/... public paths (see ASSETS const in TS).\n *\n * Injected automatically by ui/index.ts (ensureStyles); also importable directly\n * by a bundler that handles CSS imports.\n */\n\n:root {\n  /* Core palette sampled from the reference captures. */\n  --gf-yellow: #ffd21e;          /* SELECT DIFFICULTY title fill */\n  --gf-yellow-deep: #f5a800;     /* WIN gold */\n  --gf-outline: #2a2150;         /* dark title/text outline (purple-navy) */\n  --gf-green: #46c828;           /* ALLY meter / FIGHT ALONE ring / A button */\n  --gf-green-deep: #1f8a14;\n  --gf-red: #e8231b;             /* ENEMY meter / B button / INSANE pad */\n  --gf-red-deep: #a40d0d;\n  --gf-blue-pill: #5b9bd5;       /* results row pills */\n  --gf-blue-pill-deep: #2f6db0;\n  --gf-orange: #ff7a18;          /* TUFF pad / value numbers */\n  --gf-cyan: #34e0d8;            /* reload bar */\n  --gf-panel: #d9d9d9;           /* light HUD panel */\n  --gf-edit-purple: #6b4ad0;     /* pause box border / force ring */\n  --gf-text-cream: #fff4d8;\n  --gf-text-light: #eef4ff;\n}\n\n/* Generic full-screen menu surface that hosts a screen component. */\n.gf-screen {\n  position: relative;\n  width: 100%;\n  height: 100%;\n  min-height: 100%;\n  box-sizing: border-box;\n  overflow: hidden;\n  color: var(--gf-text-light);\n  font-family: \"Trebuchet MS\", \"Segoe UI\", Arial, sans-serif;\n  font-weight: 800;\n  letter-spacing: 0.02em;\n  user-select: none;\n  -webkit-user-select: none;\n}\n\n.gf-ui-scene {\n  position: absolute;\n  inset: 0;\n  z-index: 1;\n  pointer-events: none;\n}\n.gf-ui-scene-canvas {\n  display: block;\n  width: 100%;\n  height: 100%;\n}\n\n/* Gridded radial backdrop used by the menu screens (difficulty/players/force). */\n.gf-grid-bg {\n  position: absolute;\n  inset: 0;\n  background:\n    radial-gradient(circle at 50% 42%, rgba(255, 255, 255, 0.35), transparent 60%),\n    repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.08) 0 1px, transparent 1px 34px),\n    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.08) 0 1px, transparent 1px 34px);\n  background-color: var(--gf-screen-bg, #2f7fd0);\n}\n.gf-grid-bg.gf-bg-blue { --gf-screen-bg: #2f7fd0; }\n.gf-grid-bg.gf-bg-green { --gf-screen-bg: #4caa2f; }\n.gf-grid-bg.gf-bg-purple { --gf-screen-bg: #8b4fb5; }\n.gf-grid-bg.gf-bg-gold { --gf-screen-bg: #f3a312; }\n\n/*\n * The vsel00/vsel01 GLB exports contain real pad/gear/backdrop/silhouette\n * geometry, but each archive bundles EVERY vsel/challenge-select sub-menu\n * (plus, for vsel00, 40 unrelated stage-preview dioramas) into one 165-model\n * scene with no recoverable per-sub-menu grouping, so it cannot be reliably\n * auto-fit to just the relevant cluster. It is mounted as atmospheric\n * backdrop decoration (see SelectDifficulty.ts / SelectPlayers.ts); the pad\n * tiles themselves use cropped real captured native frames instead (see\n * cropImgStyle in SelectDifficulty.ts).\n */\n.gf-vsel-real-scene {\n  opacity: 0.36;\n  transform: scale(1.03);\n  filter: drop-shadow(0 20px 18px rgba(0, 0, 0, 0.32));\n}\n\n.gf-vsel-screen {\n  display: grid;\n  place-items: center;\n  background: var(--gf-vsel-outer, #2f7fd0);\n}\n.gf-vsel-frame {\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  width: min(100vw, calc(100vh * 4 / 3));\n  max-height: 100vh;\n  aspect-ratio: 4 / 3;\n  transform: translate(-50%, -50%);\n  overflow: hidden;\n}\n.gf-select-difficulty {\n  --gf-vsel-outer: #1a75d9;\n}\n.gf-select-players {\n  --gf-vsel-outer: #168c20;\n}\n.gf-vsel-screen .gf-title {\n  position: absolute;\n  left: 0;\n  right: 0;\n  top: 25.8%;\n  z-index: 3;\n  padding-top: 0;\n  display: flex;\n  justify-content: center;\n  opacity: var(--gf-title-opacity, 1);\n  transform: translateY(var(--gf-title-offset-y, 0%)) scale(var(--gf-title-scale, 1));\n  transform-origin: 50% 55%;\n}\n/* Real ascii.tpl bitmap-font rendering of the vsel title (SELECT DIFFICULTY / SELECT NUMBER OF PLAYERS). */\n.gf-vsel-title-text {\n  transform: scale(var(--gf-vsel-title-fit, 1));\n}\n.gf-vsel-screen .gf-vsel-options {\n  position: absolute;\n  inset: 0;\n  z-index: 4;\n  display: block;\n}\n\n/* Chunky outlined arcade title (SELECT DIFFICULTY, SELECT A FORCE, ...). */\n.gf-title {\n  position: relative;\n  z-index: 2;\n  text-align: center;\n  margin: 0;\n  padding-top: 0.6em;\n  font-size: clamp(22px, 4.4vw, 40px);\n  color: var(--gf-yellow);\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  -webkit-text-stroke: 2px var(--gf-outline);\n  paint-order: stroke fill;\n  text-shadow: 0 4px 0 rgba(0, 0, 0, 0.35);\n}\n\n.gf-row {\n  position: relative;\n  z-index: 2;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: clamp(16px, 5vw, 64px);\n}\n\n/* Bottom button legend shared by menu screens. */\n.gf-legend {\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: 18px;\n  z-index: 3;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: clamp(20px, 6vw, 64px);\n  font-size: clamp(13px, 2vw, 18px);\n}\n.gf-legend-item {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  color: #ffffff;\n  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.45);\n}\n\n/* The round face-button glyphs (A green / B red / X grey / Y / START). */\n.gf-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 1.7em;\n  height: 1.7em;\n  border-radius: 50%;\n  font-size: 0.9em;\n  color: #ffffff;\n  font-weight: 900;\n  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.35), 0 2px 3px rgba(0, 0, 0, 0.4);\n}\n.gf-btn-a { background: radial-gradient(circle at 35% 30%, #6fe24a, var(--gf-green-deep)); }\n.gf-btn-b { background: radial-gradient(circle at 35% 30%, #ff5a4f, var(--gf-red-deep)); }\n.gf-btn-x { background: radial-gradient(circle at 35% 30%, #cfd3da, #7d828c); color: #2a2150; }\n.gf-btn-y { background: radial-gradient(circle at 35% 30%, #6fc3ff, #2f6db0); }\n.gf-btn-start { background: radial-gradient(circle at 35% 30%, #cfd3da, #7d828c); color: #2a2150; font-size: 0.62em; }\n\n.gf-bitmap-text {\n  display: inline-flex;\n  align-items: center;\n  gap: 1px;\n  image-rendering: pixelated;\n  font-size: 0;\n}\n.gf-bitmap-glyph,\n.gf-bitmap-space {\n  display: inline-block;\n  width: 8px;\n  height: 8px;\n  flex: 0 0 auto;\n}\n.gf-bitmap-glyph {\n  background-repeat: no-repeat;\n  background-size: 128px 128px;\n}\n.gf-bitmap-fallback {\n  display: inline-block;\n  font-size: 8px;\n  line-height: 8px;\n}\n\n/* Generic option tile used by difficulty + players screens. */\n.gf-option {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 6px;\n  cursor: pointer;\n  background: none;\n  border: none;\n  color: inherit;\n  font: inherit;\n  padding: 8px;\n  transition: transform 0.12s ease;\n}\n.gf-option:hover { transform: translateY(-2px); }\n.gf-option.gf-selected { transform: scale(1.06); }\n\n.gf-vsel-screen .gf-option {\n  position: absolute;\n  padding: 0;\n  gap: 0;\n  transform:\n    translate(\n      calc(-50% + var(--gf-enter-offset-x, 0%)),\n      calc(-50% + var(--gf-enter-offset-y, 0%))\n    )\n    scale(var(--gf-select-scale, 1));\n  opacity: var(--gf-enter-opacity, 1);\n  will-change: transform, opacity;\n  transition: filter 100ms linear;\n}\n.gf-vsel-screen .gf-option:hover,\n.gf-vsel-screen .gf-option.gf-selected {\n  transform:\n    translate(\n      calc(-50% + var(--gf-enter-offset-x, 0%)),\n      calc(-50% + var(--gf-enter-offset-y, 0%))\n    )\n    scale(var(--gf-select-scale, 1));\n}\n.gf-vsel-screen .gf-motion-object {\n  transform:\n    translate(\n      calc(-50% + var(--gf-enter-offset-x, 0%)),\n      calc(-50% + var(--gf-enter-offset-y, 0%))\n    )\n    scale(var(--gf-select-scale, 1));\n  opacity: var(--gf-enter-opacity, 1);\n  will-change: transform, opacity;\n}\n.gf-vsel-screen .gf-option.gf-selected {\n  z-index: 2;\n}\n.gf-vsel-screen .gf-option.gf-selected::before {\n  content: \"\";\n  position: absolute;\n  left: 50%;\n  top: 42%;\n  width: 105%;\n  aspect-ratio: 1;\n  transform: translate(-50%, -50%) scale(var(--gf-ring-scale, 1));\n  border-radius: 50%;\n  background: #050505;\n  z-index: -1;\n  filter: drop-shadow(0 8px 0 rgba(0, 0, 0, 0.18));\n  opacity: var(--gf-ring-opacity, 1);\n}\n/*\n * Row center X/Y comes from the vsel00 scene export (option-stage ellipse) via\n * --gf-diff-row-top / --gf-diff-center-x set in SelectDifficulty.ts; the pad\n * spread (+-28.5% / +-27.5%) stays hand-tuned because the export stacks the\n * pads at the scene center. Fallbacks preserve the previous hand-tuned layout.\n */\n.gf-diff-option {\n  top: var(--gf-diff-row-top, 64%);\n  width: 22%;\n}\n.gf-diff-normal {\n  left: calc(var(--gf-diff-center-x, 51%) - 28.5%);\n  width: 29.5%;\n}\n.gf-diff-tuff {\n  left: var(--gf-diff-center-x, 51%);\n}\n.gf-diff-insane {\n  left: calc(var(--gf-diff-center-x, 51%) + 27.5%);\n}\n/*\n * Each pad tile shows a cropped region of the real captured native frame\n * (reference/captures/challenge-2-select-difficulty.png — see\n * SelectDifficulty.ts), which already bakes in the \"GF ENERGY <n> <NAME>\"\n * art pixel-for-pixel, so no separate CSS/bitmap-font callout is layered on\n * top. `.gf-diff-pad-crop` is the fixed-aspect crop window; the inner `<img>`\n * is the full capture, scaled + shifted (see cropImgStyle) so only that\n * window's pixels show.\n */\n.gf-diff-pad-crop {\n  position: relative;\n  width: 100%;\n  overflow: hidden;\n  border-radius: 8%;\n}\n.gf-capture-crop-img {\n  display: block;\n  image-rendering: -webkit-optimize-contrast;\n}\n\n.gf-player-option {\n  top: 61.5%;\n}\n.gf-player-1 {\n  left: 31%;\n  width: 31%;\n}\n.gf-player-2 {\n  left: 71%;\n  width: 31%;\n}\n/*\n * Each tile shows a cropped region of the real captured native frame\n * (reference/captures/challenge-3-select-players.png — see\n * SelectPlayers.ts), which already bakes in the silhouette/pill-label/\n * controller art pixel-for-pixel, so no separate CSS silhouette/pill/\n * controller recreation is layered on top.\n */\n.gf-player-tile-crop {\n  position: relative;\n  width: 100%;\n  overflow: hidden;\n}\n.gf-player-arrow {\n  position: absolute;\n  left: 50%;\n  top: 59.5%;\n  z-index: 4;\n  width: 7.2%;\n  transform: translate(-50%, -50%);\n  overflow: hidden;\n  border-radius: 50%;\n}\n\n/* ============================ TITLE INTRO ============================ */\n/* Source-shaped desk/title intro (research/decomp/index/title-main-menu-flow.md):\n * real tl00 scene backdrop + the G-Red desk-intro actor, replacing the old handcoded\n * CSS gear backdrop for this screen. \"Press start\" advances to the main menu, modeling\n * the title_main_menu_scene_enter -> set_global_menu_mode(9) handoff. */\n.gf-title-intro {\n  background: #10131c;\n  cursor: pointer;\n}\n.gf-title-intro-scene {\n  z-index: 1;\n}\n/* Native captured title/desk frame (reference/captures/title-main-menu.png) — cover-fit,\n * slightly dimmed so the G-Red actor layer and PRESS START read on top. */\n/* Real tl00 3D desk scene through its authored HSD camera — sits over the capture\n * (which stays as instant paint + load-failure fallback) and under the actor layer. */\n.gf-title-intro-desk {\n  position: absolute;\n  inset: 0;\n  z-index: 1;\n}\n.gf-title-intro-actor {\n  z-index: 2;\n}\n.gf-title-intro-source-title {\n  position: absolute;\n  left: 50%;\n  bottom: 15%;\n  z-index: 3;\n  max-width: 92%;\n  transform: translateX(-50%) scale(0.92);\n  transform-origin: 50% 50%;\n  opacity: 0;\n  color: #ffd21e;\n  font-size: clamp(30px, 7vh, 86px);\n  line-height: 0.92;\n  letter-spacing: 0;\n  white-space: nowrap;\n  -webkit-text-stroke: clamp(2px, 0.45vh, 5px) #071126;\n  paint-order: stroke fill;\n  text-shadow:\n    0 3px 0 #ffffff,\n    0 7px 0 rgba(0, 0, 0, 0.55),\n    0 0 18px rgba(255, 241, 126, 0.55);\n  pointer-events: none;\n  transition:\n    opacity 120ms linear,\n    transform 120ms linear;\n}\n.gf-title-intro[data-gf-intro-step=\"9\"] .gf-title-intro-source-title,\n.gf-title-intro[data-gf-intro-step=\"10\"] .gf-title-intro-source-title,\n.gf-title-intro[data-gf-intro-step=\"11\"] .gf-title-intro-source-title,\n.gf-title-intro[data-gf-intro-step=\"12\"] .gf-title-intro-source-title,\n.gf-title-intro[data-gf-intro-done=\"true\"] .gf-title-intro-source-title {\n  opacity: 1;\n  transform: translateX(-50%) scale(1);\n}\n.gf-title-intro-lightbar {\n  position: absolute;\n  left: -38%;\n  top: 66%;\n  z-index: 4;\n  width: 42%;\n  height: clamp(4px, 0.8vh, 8px);\n  opacity: 0;\n  transform: skewX(-18deg);\n  transform-origin: 50% 50%;\n  background: linear-gradient(\n    90deg,\n    transparent 0%,\n    rgba(97, 228, 255, 0.2) 18%,\n    #ffffff 50%,\n    rgba(120, 246, 255, 0.85) 70%,\n    transparent 100%\n  );\n  box-shadow:\n    0 0 10px rgba(255, 255, 255, 0.95),\n    0 0 26px rgba(70, 224, 255, 0.88),\n    0 0 54px rgba(70, 224, 255, 0.42);\n  pointer-events: none;\n}\n.gf-title-intro[data-gf-lightbar=\"active\"] .gf-title-intro-lightbar {\n  opacity: 1;\n  animation: gf-title-lightbar-sweep 700ms linear both;\n}\n.gf-title-intro-prompt {\n  position: absolute;\n  left: 50%;\n  bottom: 8%;\n  z-index: 3;\n  transform: translateX(-50%);\n  color: var(--gf-yellow);\n  font-size: clamp(18px, 3.4vw, 34px);\n  letter-spacing: 0;\n  -webkit-text-stroke: clamp(1.5px, 0.28vw, 4px) #071126;\n  paint-order: stroke fill;\n  text-shadow: 0 3px 0 #ffffff, 0 6px 0 rgba(0, 0, 0, 0.5);\n  opacity: 0;\n  animation: none;\n  pointer-events: none;\n}\n.gf-title-intro[data-gf-intro-step=\"12\"] .gf-title-intro-prompt,\n.gf-title-intro[data-gf-intro-done=\"true\"] .gf-title-intro-prompt {\n  opacity: 1;\n  animation: gf-title-prompt-blink 1.4s ease-in-out infinite;\n}\n@keyframes gf-title-lightbar-sweep {\n  from {\n    transform: translateX(0) skewX(-18deg);\n  }\n  to {\n    transform: translateX(340%) skewX(-18deg);\n  }\n}\n@keyframes gf-title-prompt-blink {\n  0%, 55% { opacity: 1; }\n  78% { opacity: 0.25; }\n  100% { opacity: 1; }\n}\n\n/* ============================ MAIN MENU ============================ */\n.gf-mainmenu {\n  background: #2ac4bc;\n}\n.gf-mainmenu-frame {\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  width: min(100%, calc(100vh * 4 / 3));\n  max-height: 100%;\n  aspect-ratio: 4 / 3;\n  transform: translate(-50%, -50%);\n  overflow: hidden;\n  background: #2ac4bc;\n  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.2);\n}\n.gf-mainmenu-source-scene {\n  position: absolute;\n  inset: 0;\n  z-index: 1;\n}\n.gf-mainmenu-source-scene .gf-ui-scene-canvas {\n  display: block;\n  width: 100%;\n  height: 100%;\n}\n.gf-mainmenu-ring {\n  position: absolute;\n  inset: 0;\n  z-index: 2;\n}\n.gf-menu-item {\n  position: absolute;\n  transform: translate(-50%, -50%);\n  cursor: pointer;\n  background: none;\n  border: none;\n  padding: 0;\n  opacity: 0;\n  outline: none;\n}\n.gf-source-menu-hit {\n  border-radius: 50%;\n}\n.gf-menu-item:focus-visible {\n  opacity: 1;\n  border-radius: 50%;\n  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.86), 0 0 0 7px rgba(232, 35, 27, 0.55);\n}\n.gf-menu-item.gf-selected:focus-visible {\n  box-shadow: 0 0 0 4px rgba(255, 255, 255, 0.92), 0 0 0 9px rgba(232, 35, 27, 0.72);\n}\n\n/* ============================ LOAD BOX DATA ============================ */\n.gf-load-box { background: #f3a312; }\n/*\n * Real exported text plate (vsel00_mdl texture_004, ASSETS.vsSelectLabels) —\n * \"LOAD BOX DATA\" / \"Insert Memory Card into Slot A\" / \"and press the (A)\n * Button.\" — shown as the actual screen art instead of recreated CSS copy.\n * The sheet is a shared multi-line atlas (also used by BattleIntro.ts), so it\n * is displayed at natural aspect ratio near the top of the screen rather than\n * pixel-cropped to a single line.\n */\n.gf-load-label-sheet {\n  position: absolute;\n  left: 50%;\n  top: 6%;\n  width: min(72vw, 620px);\n  transform: translateX(-50%);\n  image-rendering: pixelated;\n  z-index: 2;\n  filter: drop-shadow(0 4px 0 rgba(0, 0, 0, 0.28));\n}\n.gf-load-memory-icon {\n  display: block;\n  position: absolute;\n  left: 50%;\n  top: 46%;\n  width: clamp(42px, 7.8vw, 64px);\n  height: auto;\n  transform: translateX(-50%);\n  z-index: 2;\n  image-rendering: pixelated;\n  filter: drop-shadow(0 3px 0 rgba(0, 0, 0, 0.28));\n}\n.gf-box-model {\n  position: absolute;\n  left: 50%;\n  bottom: 12%;\n  width: min(44vw, 420px);\n  height: min(28vw, 270px);\n  transform: translateX(-50%);\n  z-index: 2;\n}\n.gf-box-model .gf-ui-scene-canvas {\n  display: block;\n  width: 100%;\n  height: 100%;\n  filter: drop-shadow(0 28px 20px rgba(0, 0, 0, 0.38));\n}\n\n/* ============================ SELECT A FORCE ============================ */\n/*\n * Rebuilt against reference/captures/challenge-5-select-a-force.png: the green\n * force-display platform is a captureCropImg crop of the real baked frame (see\n * SelectForce.ts doc comment), layered over the entry00 scene as atmospheric\n * backdrop. Dynamic COST/No./name/REMAIN render via bitmapText (ascii.tpl).\n */\n.gf-select-force { background: #8b4fb5; }\n.gf-select-force > .gf-select-title {\n  position: absolute;\n  left: var(--gf-select-title-left, 0);\n  top: var(--gf-select-title-top, 2%);\n  width: var(--gf-select-title-width, 100%);\n  z-index: 3;\n  padding-top: 0;\n  display: flex;\n  justify-content: center;\n}\n.gf-select-entry-scene {\n  opacity: 0.5;\n  transform: scale(1.04);\n  z-index: 1;\n}\n.gf-select-entry-scene .gf-ui-scene-canvas {\n  filter: drop-shadow(0 18px 18px rgba(0, 0, 0, 0.32));\n}\n.gf-select-pad-crop {\n  position: absolute;\n  left: var(--gf-select-pad-left, 50%);\n  top: var(--gf-select-pad-top, 47%);\n  width: min(var(--gf-select-pad-width, 58%), 620px);\n  aspect-ratio: 2410 / 300;\n  transform: translate(-50%, -50%);\n  overflow: hidden;\n  z-index: 1;\n  filter: drop-shadow(0 16px 14px rgba(0, 0, 0, 0.32));\n}\n.gf-select-pad {\n  /* Invisible hosting region for the live borg model/mini-icon fallback,\n     centered above the real platform-crop pad image. */\n  position: absolute;\n  left: var(--gf-select-pad-left, 50%);\n  top: var(--gf-select-pad-top, 47%);\n  width: min(var(--gf-select-pad-width, 45%), 420px);\n  height: min(var(--gf-select-pad-height, 17%), 150px);\n  transform: translate(-50%, -138%);\n  z-index: 2;\n}\n.gf-select-face,\n.gf-select-mini {\n  position: absolute;\n  left: 50%;\n  bottom: 6%;\n  max-width: 60%;\n  max-height: 220%;\n  object-fit: contain;\n  transform: translate(-50%, 0);\n  image-rendering: pixelated;\n  filter: drop-shadow(0 10px 0 rgba(0, 0, 0, 0.32));\n}\n.gf-select-mini-fallback {\n  display: flex;\n  align-items: flex-end;\n  justify-content: center;\n  max-width: 90%;\n}\n.gf-select-borg-scene {\n  position: absolute;\n  left: 50%;\n  bottom: 0;\n  width: min(30vw, 280px);\n  height: min(40vw, 360px);\n  transform: translate(-50%, 34%);\n  pointer-events: none;\n  filter: drop-shadow(0 14px 0 rgba(0, 0, 0, 0.32));\n}\n.gf-select-cost {\n  position: absolute;\n  left: 6%;\n  top: 66%;\n  /* Cap the block so it can never run under the force-name grid on the right. */\n  max-width: 34%;\n  z-index: 3;\n  display: flex;\n  align-items: baseline;\n  gap: 12px;\n  filter: drop-shadow(0 3px 0 rgba(0, 0, 0, 0.38));\n}\n.gf-select-name {\n  position: absolute;\n  right: 7%;\n  top: 64%;\n  z-index: 3;\n  display: grid;\n  grid-template-columns: auto minmax(120px, 1fr);\n  grid-template-areas:\n    \"no banner\"\n    \"force force\"\n    \"limit limit\";\n  gap: 6px 14px;\n  align-items: center;\n  /* Never overlap the COST readout on the left. */\n  width: min(52%, 520px);\n}\n.gf-select-no { grid-area: no; }\n.gf-select-banner {\n  grid-area: banner;\n  width: 100%;\n  max-width: 448px;\n  image-rendering: pixelated;\n  filter: drop-shadow(0 3px 0 rgba(0, 0, 0, 0.35));\n}\n.gf-select-banner-fallback { grid-area: banner; }\n.gf-select-force-name { grid-area: force; }\n.gf-select-limit { grid-area: limit; justify-self: end; }\n.gf-select-deployment { grid-column: 1 / -1; font-size: clamp(12px, 1.4vw, 18px); color: white; text-shadow: 0 1px 3px black; }\n\n/* ============================ BATTLE INTRO ============================ */\n/*\n * Rebuilt so the exported brif00 scene is the PRIMARY surface (promoted from a\n * faint low-opacity backdrop) — see BattleIntro.ts doc comment for why no\n * dedicated real capture exists for this screen. All dynamic text (names,\n * arena, energy, VS/objective copy) renders via bitmapText (ascii.tpl).\n */\n.gf-battle-intro {\n  background:\n    radial-gradient(circle at 50% 50%, rgba(255, 255, 255, 0.08), transparent 52%),\n    linear-gradient(90deg, rgba(20, 78, 156, 0.82), rgba(137, 56, 155, 0.72));\n  pointer-events: auto;\n}\n.gf-brief-real-scene {\n  opacity: 0.92;\n  filter: drop-shadow(0 22px 20px rgba(0, 0, 0, 0.4));\n}\n.gf-brief-title {\n  position: absolute;\n  left: 50%;\n  top: 5%;\n  transform: translateX(-50%);\n  margin: 0;\n  z-index: 3;\n  width: min(86%, 860px);\n  text-align: center;\n  padding-top: 0;\n  display: flex;\n  justify-content: center;\n}\n.gf-brief-side {\n  position: absolute;\n  top: 25%;\n  z-index: 3;\n  width: min(32vw, 300px);\n  min-height: 42%;\n  display: grid;\n  justify-items: center;\n  align-content: start;\n  gap: 10px;\n}\n.gf-brief-player { left: 6%; }\n.gf-brief-enemy { right: 6%; }\n.gf-brief-icon,\n.gf-brief-emblem {\n  width: min(24vw, 220px);\n  aspect-ratio: 1;\n  object-fit: contain;\n  image-rendering: pixelated;\n  filter: drop-shadow(0 8px 0 rgba(0, 0, 0, 0.35));\n}\n.gf-brief-emblem {\n  border-radius: 50%;\n  background: radial-gradient(circle, var(--gf-yellow), var(--gf-red));\n}\n.gf-brief-energy,\n.gf-brief-name {\n  padding: 4px 16px;\n  border-radius: 999px;\n  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.22), 0 3px 0 rgba(0, 0, 0, 0.24);\n  display: flex;\n  justify-content: center;\n}\n.gf-brief-energy-player { background: linear-gradient(#3ea6ff, #1262c8); }\n.gf-brief-energy-enemy { background: linear-gradient(#ff5d4c, #b81d1a); }\n.gf-brief-name {\n  max-width: 100%;\n  background: linear-gradient(#fff2a8, #dc9f18);\n}\n.gf-brief-vs {\n  position: absolute;\n  left: 50%;\n  top: 42%;\n  transform: translate(-50%, -50%) rotate(-8deg);\n  z-index: 4;\n}\n.gf-brief-vs-text { transform: scale(1.4); }\n.gf-brief-preview {\n  position: absolute;\n  left: 50%;\n  bottom: 16%;\n  transform: translateX(-50%);\n  z-index: 2;\n  width: min(44vw, 470px);\n  height: min(18vw, 170px);\n  border: 5px solid rgba(255, 255, 255, 0.8);\n  border-radius: 10px;\n  background: rgba(0, 0, 0, 0.2);\n  box-shadow: inset 0 0 0 3px rgba(0, 0, 0, 0.28), 0 8px 0 rgba(0, 0, 0, 0.35);\n}\n.gf-brief-objective {\n  position: absolute;\n  left: 50%;\n  bottom: -22px;\n  transform: translateX(-50%);\n  width: max-content;\n  max-width: 92vw;\n  padding: 7px 24px;\n  border-radius: 999px;\n  background: linear-gradient(#ffd969, #e9a51a);\n  box-shadow: 0 3px 0 rgba(0, 0, 0, 0.35);\n}\n.gf-brief-arena-name {\n  position: absolute;\n  left: 50%;\n  top: -18px;\n  transform: translateX(-50%);\n  width: max-content;\n  max-width: 92vw;\n  padding: 5px 20px;\n  border-radius: 999px;\n  background: rgba(0, 0, 0, 0.55);\n  box-shadow: 0 3px 0 rgba(0, 0, 0, 0.3);\n}\n\n/* ============================ FORCE BUILDER ============================ */\n/*\n * Rebuilt against reference/captures/challenge-6-edit-force.png: the EDIT tab\n * and active-force banner are captureCropImg crops of the real baked plates;\n * the borg grid sits over a captureCropImg crop of the real checkered floor;\n * each of the 30 ring slots is textured with a captureCropImg crop of one real\n * hex tile (see ForceBuilder.ts's COMPROMISE doc comment for why the full ring\n * isn't a single crop). Dynamic COST/LIMIT/REMAIN/names render via bitmapText.\n */\n.gf-force-screen {\n  background: #0e2138;\n}\n.gf-force-unitall-scene {\n  left: 10px;\n  top: 54px;\n  right: calc(42% + 24px);\n  bottom: 68px;\n  z-index: 3;\n  opacity: 0.16;\n  transform: scale(1.03);\n  transform-origin: center;\n  mix-blend-mode: screen;\n  filter: saturate(1.18) drop-shadow(0 18px 18px rgba(0, 0, 0, 0.36));\n}\n.gf-force { position: relative; z-index: 2; display: grid; grid-template-columns: 1fr minmax(280px, 42%); gap: 12px; padding: 12px; box-sizing: border-box; height: 100%; }\n.gf-force-screen .gf-legend { z-index: 4; }\n.gf-force-edit-tab-crop {\n  position: relative;\n  align-self: start;\n  width: min(100%, 420px);\n  aspect-ratio: 900 / 210;\n  overflow: hidden;\n  border-radius: 999px;\n  filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.4));\n}\n.gf-force-left { position: relative; display: flex; flex-direction: column; gap: 10px; min-height: 0; }\n.gf-force-floor-crop {\n  position: relative;\n  flex: 1;\n  min-height: 0;\n  overflow: hidden;\n  border-radius: 10px;\n  border: 2px solid #2f5e96;\n}\n.gf-force-floor-crop .gf-capture-crop-img { image-rendering: pixelated; }\n.gf-borg-grid {\n  position: absolute;\n  inset: 0;\n  overflow-y: auto;\n  display: grid;\n  /* The real extracted per-borg art (`mn<code>`) is a 224x32 name plate, not a\n     square icon, so each option is a wide row: [name plate | cost]. */\n  grid-template-columns: repeat(auto-fill, minmax(168px, 1fr));\n  gap: 6px;\n  padding: 10px;\n  align-content: start;\n}\n.gf-borg-cell {\n  position: relative;\n  height: 30px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 4px;\n  border-radius: 8px;\n  background: linear-gradient(rgba(139, 147, 165, 0.92), rgba(92, 99, 116, 0.92));\n  border: 2px solid #b9c4d3;\n  cursor: pointer;\n  overflow: hidden;\n  padding: 2px 4px;\n}\n.gf-borg-cell img {\n  flex: 1;\n  min-width: 0;\n  height: 100%;\n  object-fit: contain;\n  object-position: left center;\n  image-rendering: pixelated;\n}\n.gf-borg-cell .gf-borg-cell-name {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n}\n.gf-borg-cell.gf-in-force { border-color: var(--gf-yellow); box-shadow: 0 0 0 2px var(--gf-yellow) inset; }\n.gf-borg-cell.gf-disabled { opacity: 0.35; cursor: not-allowed; }\n.gf-borg-cell.gf-cursor { box-shadow: 0 0 0 2px #fff, 0 0 8px 2px rgba(255, 255, 255, 0.6); }\n.gf-borg-cell .gf-cost-tag {\n  flex: none;\n  background: rgba(0, 0, 0, 0.7);\n  padding: 1px 4px;\n  border-radius: 4px;\n}\n.gf-borg-cell .gf-new-badge {\n  position: absolute;\n  top: 0;\n  left: 0;\n  font-size: 8px;\n  color: var(--gf-yellow);\n  background: var(--gf-red);\n  padding: 0 3px;\n  border-bottom-right-radius: 4px;\n  -webkit-text-stroke: 0.4px var(--gf-outline);\n  z-index: 1;\n}\n\n.gf-force-right {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  border-radius: 10px;\n  background: radial-gradient(circle at 60% 50%, #3a2a6e, #1c1340);\n  border: 3px solid var(--gf-edit-purple);\n  padding: 10px;\n  min-height: 0;\n}\n.gf-force-banner {\n  position: relative;\n  align-self: stretch;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  height: 40px;\n  margin-bottom: 8px;\n  overflow: hidden;\n}\n.gf-force-banner-crop {\n  position: absolute;\n  inset: 0;\n  overflow: hidden;\n  border-radius: 999px;\n  z-index: 0;\n}\n.gf-force-banner-mini {\n  position: relative;\n  z-index: 1;\n  height: 26px;\n  margin-left: 44px;\n  image-rendering: pixelated;\n}\n.gf-force-banner-name {\n  position: relative;\n  z-index: 1;\n}\n.gf-borg-ring {\n  position: relative;\n  width: 100%;\n  flex: 1;\n  min-height: 200px;\n}\n/*\n * Ring band: sampled navy/purple color from the capture rather than an image\n * crop (see ForceBuilder.ts COMPROMISE doc — no single real texture covers all\n * 30 procedurally-placed slot positions).\n */\n.gf-borg-ring::before {\n  content: \"\";\n  position: absolute;\n  inset: 6%;\n  border-radius: 50%;\n  background: radial-gradient(circle at 50% 50%, transparent 62%, var(--gf-edit-purple) 63% 78%, #8f7fc9 79% 82%, transparent 83%);\n  pointer-events: none;\n  z-index: 0;\n}\n.gf-hexcell {\n  position: absolute;\n  width: 34px;\n  height: 34px;\n  transform: translate(-50%, -50%);\n  display: grid;\n  place-items: center;\n  cursor: pointer;\n  border: 0;\n  background: none;\n  padding: 0;\n  overflow: hidden;\n  z-index: 1;\n}\n.gf-hexcell-hex-tile {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  max-width: none;\n  object-fit: fill;\n  z-index: 0;\n}\n.gf-hexcell.gf-hexcell-empty .gf-hexcell-hex-tile { filter: grayscale(0.6) brightness(0.55) saturate(0.7); }\n.gf-hexcell-no {\n  position: relative;\n  z-index: 1;\n  transform: scale(0.85);\n}\n.gf-hexcell.gf-hexcell-filled .gf-hexcell-no { display: none; }\n.gf-hexcell-img {\n  position: absolute;\n  inset: 0;\n  z-index: 1;\n  width: 88%;\n  height: 88%;\n  margin: auto;\n  object-fit: contain;\n  image-rendering: pixelated;\n}\n.gf-hexcell.gf-hexcell-active { filter: drop-shadow(0 0 0 2px var(--gf-red)); }\n.gf-hexcell.gf-cursor { filter: drop-shadow(0 0 3px #fff) drop-shadow(0 0 6px #fff); }\n\n.gf-cost-panel {\n  position: absolute;\n  right: 6%;\n  top: 38%;\n  width: 46%;\n  background: linear-gradient(#1f3f6e, #172e56);\n  border: 2px solid #b3b3b3;\n  border-radius: 4px;\n  padding: 6px 8px;\n  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.5);\n}\n.gf-cost-panel .gf-cost-line {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  gap: 8px;\n}\n.gf-cost-panel .gf-cost-total {\n  border-bottom: 2px solid #9aa0ab;\n  padding-bottom: 4px;\n  margin-bottom: 4px;\n}\n.gf-cost-panel .gf-cost-val { transform: scale(0.9); }\n.gf-cost-panel.gf-over .gf-cost-val.gf-remain { filter: hue-rotate(0deg); }\n.gf-force-legend .gf-legend-item { display: inline-flex; align-items: center; gap: 6px; }\n.gf-legend-glyph { opacity: 0.9; }\n\n/* ============================ BATTLE HUD ============================ */\n/* Rebuilt 1:1 against reference/captures/challenge-8-in-battle-hud.png and\n   challenge-9-battle-critical-hp.png. The HUD is authored on the game's\n   native 640x480 frame; BattleHud.ts scales the whole stage to the container\n   (non-uniform, like the real frame stretching to the viewport). All element\n   positions live in BattleHud.ts with the capture-measured %s commented. */\n.gf-hud {\n  position: absolute;\n  left: 0;\n  top: 0;\n  width: 640px;\n  height: 480px;\n  transform-origin: 0 0;\n  pointer-events: none;\n  z-index: 10;\n}\n.gf-hud .gf-hidden {\n  display: none;\n}\n.gf-hud-vector {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  overflow: visible;\n}\n/* absolutely positioned real ascii.tpl bitmap text on the 640x480 stage */\n.gf-hud-text {\n  position: absolute;\n}\n/*\n * TUNED readability guard: the ascii.tpl bold block bakes in a black outline\n * (see bitmapText.ts), which is enough contrast for every HUD text node that\n * sits on its own solid/translucent plate (energy tabs, alert roundel, timer\n * pill, X/B button discs, critical HP capsule). A few elements float BARE\n * over the raw 3D scene with nothing behind them but the stage's fog/clear\n * color: the at-rest HP ring digits, ammo/X-ammo digits, the DEFEATED\n * banner, and the \"1P\"/\"2P\" player tag. Checked against the real 40-stage\n * render-state export extremes (st10 fog #000000, luma 0; st0b/st24/st2b/\n * st44/st4b fog #e8ffe8, luma ~248 — see research/asset-coverage audit) the\n * single baked outline plus the pre-existing 1px drop-shadow was too weak on\n * the near-white stages (verified with a throwaway harness rendering\n * BattleHud.ts directly over #000000 and #e8ffe8). This four-direction dark\n * halo is a presentation-only addition (no ROM/HUD-sprite source — the\n * decoded HUD has no separate text-shadow layer) sized to stay under the\n * glyphs' own baked outline so it does not change their read shape.\n */\n.gf-hp-num .gf-bitmap-glyph,\n.gf-ammo-num .gf-bitmap-glyph,\n.gf-xammo-num .gf-bitmap-glyph,\n.gf-defeated-text .gf-bitmap-glyph,\n.gf-player-label .gf-bitmap-glyph {\n  filter: drop-shadow(1px 0 0 rgba(10, 14, 30, 0.9)) drop-shadow(-1px 0 0 rgba(10, 14, 30, 0.9))\n    drop-shadow(0 1px 0 rgba(10, 14, 30, 0.9)) drop-shadow(0 -1px 0 rgba(10, 14, 30, 0.9));\n}\n/* ally energy number is centered in its tab segment (x 196..242 measured) */\n.gf-ally-num {\n  width: 46px;\n  justify-content: center;\n}\n/* HP digits move into the red capsule in the critical state (challenge-9) */\n.gf-hp-num.gf-critical {\n  left: 66px !important;\n  top: 402px !important;\n}\n/* top-center timer pill (untimed challenge battles hide it) */\n.gf-hud-timer {\n  position: absolute;\n  top: 8px;\n  left: 320px;\n  transform: translateX(-50%);\n  min-width: 78px;\n  height: 26px;\n  display: grid;\n  place-items: center;\n  border-radius: 999px;\n  background: linear-gradient(#eef2f7, #9aa0ab);\n  border: 2px solid #ffffff;\n  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.24);\n}\n.gf-hud-timer.gf-hidden {\n  display: none;\n}\n/* real per-borg bn<code> name banner (optional slot) */\n.gf-hud-banner {\n  position: absolute;\n  top: 40px;\n  left: 320px;\n  transform: translateX(-50%);\n  height: 28px;\n  image-rendering: pixelated;\n}\n/* floating teammate plates (\"CPU\"/\"ALLY\" + green-on-red mini HP bar).\n   challenge-8 example: CPU label at 56..60%W / 21.5..23.5%H, bar 63x6px below. */\n.gf-hud-mates {\n  position: absolute;\n  inset: 0;\n}\n.gf-mate {\n  position: absolute;\n  transform: translateX(-50%);\n  display: grid;\n  grid-template-columns: 18px 63px;\n  grid-template-rows: auto auto;\n  column-gap: 4px;\n  row-gap: 3px;\n  align-items: center;\n}\n.gf-mate-roundel {\n  grid-row: 1 / 3;\n  width: 18px;\n  height: 18px;\n  object-fit: contain;\n  image-rendering: pixelated;\n  filter: drop-shadow(1px 1px 0 rgba(16, 24, 60, 0.75));\n}\n.gf-mate-label {\n  grid-column: 2;\n  min-width: 63px;\n  height: 18px;\n}\n/*\n * TUNED readability guard (matches the .gf-hp-num/.gf-ammo-num etc. rule\n * above): the floating teammate label has no backing plate and uses the\n * THIN (untinted-white, no baked outline) ascii.tpl block, so a single 1px\n * diagonal shadow measured too weak against the near-white stage extremes\n * (st0b/st24/st2b/st44/st4b) in the readability harness. Widened to a\n * four-direction halo for the same reason.\n */\n.gf-mate-label .gf-bitmap-glyph {\n  filter: drop-shadow(1px 0 0 rgba(16, 24, 60, 0.9)) drop-shadow(-1px 0 0 rgba(16, 24, 60, 0.9))\n    drop-shadow(0 1px 0 rgba(16, 24, 60, 0.9)) drop-shadow(0 -1px 0 rgba(16, 24, 60, 0.9));\n}\n.gf-mate-bar {\n  grid-column: 2;\n  width: 63px;\n  height: 6px;\n  background: #f2200a;\n  border: 1px solid rgba(0, 0, 0, 0.7);\n}\n.gf-mate-fill {\n  height: 100%;\n  background: #2ce518;\n}\n\n/* ============================ RESULTS ============================ */\n/*\n * Rebuilt so the exported rpot20 (win) / rpot23 (lose) podium scene is the\n * PRIMARY surface (promoted from a faint backdrop). Row LABELS are one real\n * captureCropImg crop of the baked pill stack (fixed text, same every result);\n * per-battle VALUES render via bitmapText. See Results.ts doc comment.\n */\n.gf-results { background: #6a3f2a; }\n.gf-results::after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  z-index: 1;\n  background: linear-gradient(90deg, rgba(0, 0, 0, 0.28), rgba(0, 0, 0, 0.04) 54%, rgba(0, 0, 0, 0.12));\n  pointer-events: none;\n}\n.gf-results-real-scene {\n  z-index: 0;\n  opacity: 1;\n  filter: drop-shadow(0 20px 20px rgba(0, 0, 0, 0.38));\n}\n/*\n * Row horizontal extent comes from the rpot20/rpot23 scene exports (row pills\n * normalized against the 640x480 screen quad) via vars set in Results.ts; the\n * vertical placement stays hand-tuned because the export is a rest pose (see\n * the generated anchor's caveat). Fallbacks preserve the hand-tuned layout.\n */\n.gf-results-labels-crop {\n  position: absolute;\n  left: var(--gf-results-rows-left, 6%);\n  top: 6%;\n  height: 88%;\n  aspect-ratio: 785 / 1355;\n  overflow: hidden;\n  z-index: 2;\n  filter: drop-shadow(0 3px 3px rgba(0, 0, 0, 0.3));\n}\n.gf-results-rows {\n  position: absolute;\n  left: var(--gf-results-rows-left, 6%);\n  top: 6%;\n  height: 88%;\n  aspect-ratio: 785 / 1355;\n  display: flex;\n  flex-direction: column;\n  z-index: 3;\n}\n.gf-result-row { flex: 1; display: flex; align-items: center; }\n.gf-result-label-spacer { flex: 1.8; }\n.gf-result-val {\n  flex: 1;\n  display: flex;\n  justify-content: flex-end;\n  padding-right: 6%;\n}\n.gf-result-grand .gf-result-val { padding-right: 4%; }\n.gf-results-verdict {\n  position: absolute;\n  left: 42%;\n  top: 44%;\n  transform: translate(-50%, -50%) rotate(-6deg);\n  z-index: 3;\n}\n.gf-verdict-win .gf-bitmap-text { filter: drop-shadow(0 4px 0 rgba(0, 0, 0, 0.4)); }\n.gf-verdict-lose {\n  left: 50%;\n  top: 36%;\n  transform: translate(-50%, -50%) rotate(-3deg);\n}\n.gf-results-start {\n  position: absolute;\n  right: 18px;\n  bottom: 18px;\n  z-index: 4;\n  padding: 6px 14px;\n  border-radius: 999px;\n  background: rgba(0, 0, 0, 0.55);\n  filter: drop-shadow(0 3px 0 rgba(0, 0, 0, 0.35));\n}\n\n/* ============================ PAUSE MENU ============================ */\n.gf-pause-overlay {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  place-items: center;\n  background: rgba(0, 0, 0, 0.18);\n  z-index: 20;\n}\n/*\n * RECREATED (no original pause-menu asset found) — see PauseMenu.ts header.\n * The panel reuses an existing exported glossy roundel plate texture\n * (ASSETS.menuRoundelPlate) as its backing art instead of a flat CSS gradient\n * box; the purple border/shape remain a minimal, gamepad-safe recreation.\n */\n.gf-pause-panel {\n  position: relative;\n  min-width: 260px;\n  border-radius: 16px;\n  background: #aeb4c0;\n  border: 4px solid var(--gf-edit-purple);\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);\n  overflow: hidden;\n}\n.gf-pause-plate {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  opacity: 0.55;\n  mix-blend-mode: luminosity;\n  pointer-events: none;\n  z-index: 0;\n}\n.gf-pause-panel > :not(.gf-pause-plate) {\n  position: relative;\n  z-index: 1;\n}\n.gf-pause-title {\n  min-height: 42px;\n  display: grid;\n  place-items: center;\n  padding: 8px 0;\n  color: var(--gf-outline);\n}\n.gf-pause-items { padding: 8px 14px 16px; display: flex; flex-direction: column; gap: 8px; }\n.gf-pause-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  min-height: 36px;\n  padding: 6px 12px;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.4);\n  color: var(--gf-outline);\n  cursor: pointer;\n  border: none;\n  font-family: inherit;\n  font-weight: 800;\n}\n.gf-pause-item.gf-selected {\n  background: linear-gradient(#6f9bd8, #2f6db0);\n  color: #fff;\n}\n.gf-pause-item .gf-pause-bullet { width: 1.4em; }\n.gf-pause-title-text {\n  transform: scale(2.65);\n  transform-origin: center;\n  filter: drop-shadow(1px 1px 0 rgba(255, 255, 255, 0.55));\n}\n.gf-pause-item-text {\n  transform: scale(2.15);\n  transform-origin: left center;\n  filter: drop-shadow(1px 1px 0 rgba(255, 255, 255, 0.45));\n}\n.gf-pause-item.gf-selected .gf-pause-item-text {\n  filter: drop-shadow(1px 1px 0 rgba(0, 0, 0, 0.65));\n}\n\n/* ============================ GETS (Borg GET drop list) ============================ */\n/* TUNED minimal recreation — see Gets.ts header. Deliberately simple: a static list of\n   this battle's rolled drops over the real getStrip (gets00_mdl) texture, no per-drop\n   box-open cinematic (future work). */\n.gf-gets {\n  background: #1a2f4a;\n  display: grid;\n  place-items: center;\n}\n.gf-gets-backdrop {\n  position: absolute;\n  top: 8%;\n  left: 50%;\n  transform: translateX(-50%);\n  width: min(80vw, 448px);\n  image-rendering: pixelated;\n  filter: drop-shadow(0 6px 10px rgba(0, 0, 0, 0.4));\n  z-index: 0;\n}\n.gf-gets-title {\n  position: absolute;\n  top: 6%;\n  left: 50%;\n  transform: translateX(-50%) scale(3);\n  z-index: 2;\n  color: var(--gf-yellow);\n  filter: drop-shadow(1px 1px 0 var(--gf-outline));\n}\n.gf-gets-rows {\n  position: relative;\n  z-index: 1;\n  margin-top: 18%;\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n  min-width: min(80vw, 420px);\n}\n.gf-gets-row {\n  padding: 10px 18px;\n  border-radius: 999px;\n  background: linear-gradient(#7fb4e6, var(--gf-blue-pill-deep));\n  border: 2px solid #bcdcff;\n  box-shadow: inset 0 -2px 0 rgba(0, 0, 0, 0.25);\n  text-align: center;\n}\n.gf-gets-row-parts { background: linear-gradient(#f0c26a, #b5813a); border-color: #ffdf9c; }\n.gf-gets-row-text {\n  transform: scale(1.6);\n  transform-origin: center;\n  filter: drop-shadow(1px 1px 0 rgba(0, 0, 0, 0.55));\n}\n.gf-gets-prompt {\n  position: absolute;\n  right: 18px;\n  bottom: 18px;\n  z-index: 2;\n  color: #fff;\n  font-size: clamp(11px, 1.6vw, 15px);\n  letter-spacing: 0.06em;\n  -webkit-text-stroke: 0.5px var(--gf-outline);\n  paint-order: stroke fill;\n}\n\n/* The editor commit control remains readable without exported bitmap assets. */\n.gf-force-save {\n  display: block; width: 100%; margin-top: 8px; padding: 8px;\n  color: #fff; background: #244c80; border: 2px solid #bcdcff;\n  font: bold 12px sans-serif; cursor: pointer;\n}\n.gf-force-save:focus-visible { outline: 3px solid #fff; outline-offset: 2px; }\n.gf-force-save:disabled { opacity: .5; cursor: default; }\n";
